// 复用实际钱货夹具但不运行原事务矩阵；本节点只验证真实路遇战斗产生的货物处置。
#define main dynamic_affairs_fixture_main
#include "dynamic_affairs_test.cpp"
#undef main
#include "resident/kernel/task_cargo_access.hpp"
namespace {
// 战斗通过真实install_encounter、preview_personal/apply_personal与回合解析生成，不写伪造终局。
struct CargoScenario {
    Fixture f;PersonalCatalog personal_catalog;PersonalState personal;PersonalAccess personal_access;StableId task_id,contract_id,battle_id;Integer target=200;
    explicit CargoScenario(bool policy_enabled=true,bool small_receiver=false,bool eligible=true){
        f.common.state().wallets.find("public")->balance=2000;f.common.state().inventories.find("market")->lots.front().quantity=200;auto* policy=f.affairs_catalog.policies.find("grain_policy");policy->max_claim_quantity=200;policy->purchase_budget_per_unit=3;policy->reward_per_unit=1;auto* offer=f.tasks.offer_instances.find(f.offer_id());offer->definition.goal.quantity=200;offer->definition.budget=600;offer->definition.reward=200;refresh();if(eligible){auto action=f.begin(f.command("accept_offer",200));task_id=f.tasks.actions.find(action)->task_id;finish_task(action,1);contract_id=*f.tasks.tasks.find(task_id)->contract_id;f.buy(task_id,200);}f.catalog->items.insert("sword",{"sword",1,1,true});auto* opponent=f.common.state().actors.find("npc");opponent->combat.weapon_id="sword";opponent->attributes.martial=100;require(f.common.apply_resources({{AddLot{"bag:npc","sword",1,person("npc"),{}}}, {}}));if(small_receiver)require(f.common.apply_resources({{SetInventoryCapacity{"bag:npc",1}}, {}}));personal_catalog.enabled=true;PersonalWeapon weapon;weapon.category="sword";weapon.minimum_range=0;weapon.maximum_range=100;weapon.arc_degrees=360;weapon.damage=100;weapon.stamina_cost=0;weapon.recovery_rounds=0;weapon.move_distance=50;personal_catalog.weapons.insert("sword",weapon);PersonalArena arena;arena.id="arena";arena.width=300;arena.height=300;arena.spawns={{0,0,{100,100},{}},{1,180,{150,100},{}}};personal_catalog.arenas.insert(arena.id,arena);PersonalObjective objective;objective.id="road_combat";objective.kind="skirmish";objective.max_rounds=8;objective.injury_on_defeat=1;personal_catalog.objectives.insert(objective.id,objective);PersonalTerms terms;terms.battlefield_id=arena.id;terms.objective_id=objective.id;if(policy_enabled){TaskCargoPolicy cargo;cargo.id="declared_road_cargo";cargo.task_template_id="supply";cargo.item_id="grain";cargo.transfer_cap=15;cargo.destroy_cap=5;terms.cargo_policy=std::make_shared<const TaskCargoPolicy>(cargo);}personal_catalog.road_conflicts.insert("npc",terms);f.access.set_journey_encounter=[](const StableId& id,const StableId&,bool){return id.empty()?common_success():common_failure("UnexpectedTestJourney");};personal_access.occupied=[](const StableId&){return false;};personal_access.on_battle_started=[&](const PersonalBattle& battle){TaskCargoAccess source(f.common,personal,personal_catalog,f.interaction);return freeze_task_cargo_exposure(f.common,f.tasks,battle.id,source);};personal_access.on_battle_result=[&](const PersonalBattle& battle){TaskCargoAccess source(f.common,personal,personal_catalog,f.interaction);return apply_task_cargo_result(f.common,f.tasks,battle.id,source);};
        EncounterInstall contact;contact.leaders={"player","npc"};contact.anchors={Location{WildernessLocation{"test_map","office",{0,0}}},Location{WildernessLocation{"test_map","office",{0,0}}}};contact.apply_motion=[&](const StableId&,bool){for(std::size_t i=0;i<2;++i){ActorMutation movement;movement.actor_id=contact.leaders[i];movement.location=contact.anchors[i];auto moved=f.common.apply_actor(movement);if(!moved.ok)return moved;}return common_success();};auto encounter=require(install_encounter(f.common,f.interaction,"player",contact));++f.common.state().identity.tick;PersonalCommand start;start.kind="encounter_fight";start.encounter_id=encounter;auto quote=require(preview_personal(f.common,personal,personal_catalog,f.interaction,f.interaction_catalog,f.access,personal_access,"player",start));battle_id=require(apply_personal(f.common,personal,personal_catalog,f.interaction,f.interaction_catalog,f.access,personal_access,"player",quote)).battle_id;
    }
    // 供给观察使用此夹具声明的200单位目标，避免借旧10单位目标改变冻结合同。
    void refresh(){f.known.tick=f.common.tick();SupplyObservation observation{"city_grain","org.city","office","store","grain","source:grain",target,f.stock(),f.common.inventory("store")->revision};require(reconcile_affairs(f.common,f.affairs,f.affairs_catalog,f.tasks,{observation},f,f.common.tick()));require(publish_need_offers(f.common,f.affairs,f.affairs_catalog,f.tasks,f.task_catalog,f.common.tick()));}
    void finish_task(const StableId& id,Integer tick){auto action=*f.common.action(id);f.common.state().identity.tick=tick;require(finish_dynamic_task_action(f.common,f.tasks,f.interaction,f.interaction_catalog,f.access,action,tick,f.affairs));require(f.common.apply_action({ActionMutation::Kind::erase,action,{},{},{}}));ActorMutation free;free.actor_id="player";free.action_id="";require(f.common.apply_actor(free));f.tasks.actions.erase(id);refresh();}
    // 玩家只提交合法等待输入，敌方AI和伤害仍由原个人战规则决定。
    void fight(){for(Integer i=0;i<8&&personal.battles.find(battle_id)->phase=="planning";++i){const auto* unit=personal.battles.find(battle_id)->units.find("player");PersonalCommand command;command.kind="battle_plan";command.battle_id=battle_id;command.plan=PersonalPlan{unit->position,unit->heading,"wait",{},{},{}};auto quote=require(preview_personal(f.common,personal,personal_catalog,f.interaction,f.interaction_catalog,f.access,personal_access,"player",command));require(apply_personal(f.common,personal,personal_catalog,f.interaction,f.interaction_catalog,f.access,personal_access,"player",quote));}check(personal.battles.find(battle_id)->outcome=="defeat"&&personal.battles.find(battle_id)->applied,"actual personal engine produces declared defeat fact");require(validate_personal(f.common,personal,personal_catalog,f.interaction));}
    Integer carrier_grain()const{return require(f.common.count("bag:player","grain",{Owner{Owner::Kind::task,task_id,{}}}));}
    Integer recipient_grain()const{return require(f.common.count("bag:npc","grain",{person("npc")}));}
    Integer total_grain()const{Integer total=0;for(const auto& inventory:f.common.state().inventories.rows())for(const auto& lot:inventory.second.lots)if(lot.item_id=="grain")total+=lot.quantity;return total;}
    void validate(){TaskCargoAccess source(f.common,personal,personal_catalog,f.interaction);require(validate_task_cargo_sources(f.common,f.tasks,source));require(validate_dynamic_tasks(f.common,f.tasks,f.task_catalog,*f.catalog));require(validate_affairs(f.common,f.affairs,f.affairs_catalog,f.tasks));require(f.common.validate_common());}
};
// 成功路径串起真实战斗、资产、部分交付和自然清算；货损没有交付奖励。
void real_disposition(){CargoScenario game;auto& f=game.f;TaskCargoAccess source(f.common,game.personal,game.personal_catalog,f.interaction);check(f.tasks.cargo_exposures.size()==1&&f.tasks.cargo_exposures.find(game.battle_id)->frozen_quantity==200&&game.carrier_grain()==200,"actual battle start freezes existing task cargo without applying loss");auto id=f.common.state().next_instance_id;check(!apply_task_cargo_result(f.common,f.tasks,game.battle_id,source).ok&&f.common.state().next_instance_id==id,"pending battle cannot authorize cargo loss");require(freeze_task_cargo_exposure(f.common,f.tasks,game.battle_id,source));check(f.tasks.cargo_exposures.size()==1,"duplicate battle-start callback is idempotent");auto point=require(f.common.begin_savepoint());require(f.common.apply_resources({{TransferLots{"bag:player","market","grain",1,{Owner{Owner::Kind::task,game.task_id,{}}},{},person("clerk")}}, {}}));check(!validate_task_cargo_sources(f.common,f.tasks,source).ok,"pending source rejects changed cargo custody and manifest");require(f.common.rollback_savepoint(point));game.validate();
    CodecVisitor::Buffer before;CodecVisitor writer(before);require(visit_task_checkpoint(writer,f.tasks));require(visit_dynamic_task_checkpoint(writer,f.tasks));require(visit_personal_checkpoint(writer,game.personal));require(writer.finish());TaskState resumed_tasks;PersonalState resumed_personal;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(before));require(visit_task_checkpoint(reader,resumed_tasks));require(visit_dynamic_task_checkpoint(reader,resumed_tasks));require(visit_personal_checkpoint(reader,resumed_personal));require(reader.finish());TaskCargoAccess restored_source(f.common,resumed_personal,game.personal_catalog,f.interaction);require(validate_task_cargo_sources(f.common,resumed_tasks,restored_source));check(resumed_tasks.cargo_exposures.find(game.battle_id)->resolution==TaskCargoResolution::pending,"pending manifest and source resume without re-freezing quantities");
    const auto pending_tasks=f.tasks;const auto pending_personal=game.personal;const auto pending_interaction=f.interaction;const auto counter=f.common.state().next_instance_id;auto transaction=require(f.common.begin_savepoint());game.fight();auto failed=f.common.apply_resources({{WalletDelta{"missing_wallet",-1,true}}, {}});check(!failed.ok,"later candidate failure occurs after actual cargo transfer and sink");require(f.common.rollback_savepoint(transaction));f.tasks=pending_tasks;game.personal=pending_personal;f.interaction=pending_interaction;check(game.carrier_grain()==200&&game.recipient_grain()==0&&f.tasks.cargo_dispositions.empty()&&!f.common.state().facts.find(game.battle_id)&&f.common.state().next_instance_id==counter&&game.personal.battles.find(game.battle_id)->phase=="planning","whole candidate rollback restores actual combat result, cargo, source consumption and IDs");game.validate();game.fight();check(game.carrier_grain()==180&&game.recipient_grain()==15&&game.total_grain()==195&&f.tasks.cargo_dispositions.size()==1,"200 cargo becomes180 carried plus15 actual recipient plus5 destroyed");auto totals=require(task_cargo_totals(f.tasks,game.contract_id));check(totals.transferred_quantity==15&&totals.destroyed_quantity==5&&f.tasks.deliveries.empty()&&f.common.wallet("wallet:player")->balance==0,"source-certified loss totals do not create delivery credit or reward");id=f.common.state().next_instance_id;require(apply_task_cargo_result(f.common,f.tasks,game.battle_id,source));check(f.common.state().next_instance_id==id&&f.tasks.cargo_dispositions.size()==1&&game.carrier_grain()==180,"real result replay cannot transfer or destroy cargo twice");auto forged_personal=game.personal;forged_personal.facts.find(game.battle_id)->result_id="other_result";TaskCargoAccess forged(f.common,forged_personal,game.personal_catalog,f.interaction);check(!validate_task_cargo_sources(f.common,f.tasks,forged).ok,"restore rejects mismatch with actual battle result authority");auto replayed=f.tasks;replayed.contracts.find(game.contract_id)->cargo_disposition_ids.push_back(replayed.contracts.find(game.contract_id)->cargo_disposition_ids.front());check(!task_cargo_totals(replayed,game.contract_id).ok,"duplicate source receipt cannot count toward exhausted-cargo closure twice");auto bad_participants=f.interaction;bad_participants.encounters.front().participants.push_back("clerk");TaskCargoAccess wrong_members(f.common,game.personal,game.personal_catalog,bad_participants);check(!validate_task_cargo_sources(f.common,f.tasks,wrong_members).ok,"source rejects extra participant outside actual battle parties");auto bad_tasks=f.tasks;bad_tasks.cargo_dispositions.rows().front().second.destroyed_quantity=6;check(!validate_task_cargo_integrity(f.common,bad_tasks).ok,"restore rejects altered disposition conservation");game.validate();
    PersonalCommand close_command;close_command.kind="battle_close";close_command.battle_id=game.battle_id;auto battle_close=require(preview_personal(f.common,game.personal,game.personal_catalog,f.interaction,f.interaction_catalog,f.access,game.personal_access,"player",close_command));require(apply_personal(f.common,game.personal,game.personal_catalog,f.interaction,f.interaction_catalog,f.access,game.personal_access,"player",battle_close));f.move("office");auto report=f.begin(f.command("report_offer",180));game.finish_task(report,f.common.tick()+1);const auto* contract=f.tasks.contracts.find(game.contract_id);check(contract->status==ContractStatus::settled&&contract->stop_reason=="cargo_loss"&&contract->delivered_quantity==180&&contract->paid_reward==180&&contract->refunded_budget==200,"surviving actual hand-in naturally settles proportional reward and unused budget");check(f.common.wallet("public")->balance==1420&&f.common.wallet("wallet:player")->balance==180&&f.common.wallet("merchant")->balance==400,"partial-loss money is exactly conserved with no cancellation shortcut");check(f.affairs.claims.find(contract->source_binding.claim_id)->status==ClaimStatus::released&&f.affairs.claims.find(contract->source_binding.claim_id)->fulfilled_amount==180,"only actual180 delivery fulfills the claim and remaining share is released");game.validate();auto missing_encounter=f.interaction;missing_encounter.encounters.clear();TaskCargoAccess missing_source(f.common,game.personal,game.personal_catalog,missing_encounter);check(!validate_task_cargo_sources(f.common,f.tasks,missing_source).ok,"declared policy battle cannot lose its retained encounter authority");ActorMutation later;later.actor_id="npc";later.location=SettlementLocation{"other","remote"};require(f.common.apply_actor(later));require(f.common.apply_resources({{TransferLots{"bag:npc","market","grain",15,{person("npc")},{},person("clerk")}}, {}}));game.validate();check(true,"historical receipt survives recipient movement and later goods disposal");CodecVisitor::Buffer after;CodecVisitor after_writer(after);require(visit_task_checkpoint(after_writer,f.tasks));require(visit_dynamic_task_checkpoint(after_writer,f.tasks));require(visit_personal_checkpoint(after_writer,game.personal));require(after_writer.finish());TaskState loaded;PersonalState loaded_personal;CodecVisitor after_reader(static_cast<const CodecVisitor::Buffer&>(after));require(visit_task_checkpoint(after_reader,loaded));require(visit_dynamic_task_checkpoint(after_reader,loaded));require(visit_personal_checkpoint(after_reader,loaded_personal));require(after_reader.finish());TaskCargoAccess loaded_source(f.common,loaded_personal,game.personal_catalog,f.interaction);require(validate_task_cargo_sources(f.common,loaded,loaded_source));check(loaded.cargo_dispositions.size()==1&&require(task_cargo_totals(loaded,game.contract_id)).destroyed_quantity==5,"settled receipt restores once with historical source proof");}
// 接收方容量不可用、无货和未声明政策都走明确无损分支，原战斗继续完成。
void skipped_sources(){CargoScenario full(true,true);full.fight();check(full.carrier_grain()==200&&full.recipient_grain()==0&&full.f.tasks.cargo_dispositions.empty()&&full.f.tasks.cargo_exposures.find(full.battle_id)->resolution_reason=="recipient_unavailable","full real recipient skips the entire frozen pair without destroying cargo");full.validate();CargoScenario empty(true,false,false);empty.fight();check(empty.f.tasks.cargo_exposures.size()==1&&empty.f.tasks.cargo_exposures.find(empty.battle_id)->resolution_reason=="no_eligible_cargo"&&empty.f.tasks.cargo_dispositions.empty(),"declared no-cargo encounter keeps explicit once-only skipped source proof");empty.validate();CargoScenario undeclared(false);undeclared.fight();check(undeclared.carrier_grain()==200&&undeclared.f.tasks.cargo_exposures.empty()&&undeclared.f.tasks.cargo_dispositions.empty(),"undeclared road conflict cannot turn defeat into default cargo loss");undeclared.validate();}
}
int main(){try{real_disposition();skipped_sources();}catch(const std::exception& error){++failures;std::cerr<<"EXCEPTION "<<error.what()<<'\n';}std::cout<<"TASK_CARGO_DISPOSITION "<<checks<<" checks "<<failures<<" failures\n";return failures?1:0;}
